B.bo=s(["ROUTLEDGE"],t.s)
B.ayp=new A.e(u.uY,u.Af,"Bu delil, ak\u0131l y\xfcr\xfctmenin ve mant\u0131k yasalar\u0131n\u0131n fiziksel nesneler gibi ge\xe7ici olmad\u0131\u011f\u0131n\u0131 vurgular. \u0130nsan zihni hakikate ula\u015fabildi\u011fini varsayar; bilim ve felsefe de bu g\xfcven \xfczerine kurulur. E\u011fer ger\xe7eklik b\xfct\xfcn\xfcyle k\xf6r ve ak\u0131ls\u0131z s\xfcre\xe7lerin \xfcr\xfcn\xfc ise, akl\u0131n hakikate uygunlu\u011fu ayr\u0131ca a\xe7\u0131klama ister. Teist a\xe7\u0131klamada ak\u0131l ile evrenin uyumu, her ikisinin de ilim sahibi bir kayna\u011fa dayanmas\u0131yla anlam kazan\u0131r. Bu nedenle \u201cMant\u0131k Yasalar\u0131 Delili\u201d tek ba\u015f\u0131na kapal\u0131 bir slogan de\u011fil, bir a\xe7\u0131klama aray\u0131\u015f\u0131d\u0131r. Kart\u0131n k\u0131sa iddias\u0131 \u015fudur: De\u011fi\u015fmeyen mant\u0131k ilkeleri, maddi evrenden daha temel g\xf6r\xfcn\xfcr. Bu iddia do\u011frudan g\xf6zlenen olgu ile nihai metafizik a\xe7\u0131klama aras\u0131ndaki ba\u011f\u0131 kurar. Allah\u2019\u0131n varl\u0131\u011f\u0131 lehine de\u011feri, bu olgunun tesad\xfcf, k\xf6r zorunluluk veya a\xe7\u0131klamas\u0131z kabul ile b\u0131rak\u0131ld\u0131\u011f\u0131nda eksik kalmas\u0131d\u0131r.")
B.aa2=new A.b("DELIL-0011","Felsefi ve Kel\xe2m\xee Deliller","Klasik arg\xfcmanlar","Mant\u0131k Yasalar\u0131 Delili","De\u011fi\u015fmeyen mant\u0131k ilkeleri, maddi evrenden daha temel g\xf6r\xfcn\xfcr.","\xc7eli\u015fmezlik, \xf6zde\u015flik, \xe7\u0131kar\u0131m gibi ilkeler fiziksel nesne de\u011fildir; ama t\xfcm d\xfc\u015f\xfcncenin temelidir. Teist bak\u0131\u015fta bunlar Allah\u2019\u0131n ilmi ve hikmetiyle uyumlu bir akledilebilirlik d\xfczenine i\u015faret eder.",B.zL,"orta",B.bo,B.ayp)
