B.ak0=new A.b("DELIL-0026","Bilimsel ve Do\u011fa \xdczerinden Deliller","Kozmos, canl\u0131l\u0131k, bilin\xe7","\u0130nce Ayar Delili","Fizik sabitleri ve ba\u015flang\u0131\xe7 ko\u015fullar\u0131, ya\u015fam i\xe7in dar aral\u0131klarda g\xf6r\xfcn\xfcr.","SEP\u2019in fine-tuning tart\u0131\u015fmas\u0131nda belirtildi\u011fi gibi arg\xfcman, yasalar, sabitler ve s\u0131n\u0131r ko\u015fullar\u0131 farkl\u0131 olsayd\u0131 ya\u015fam\u0131n \xe7\u0131kmas\u0131n\u0131n \xe7ok zor olaca\u011f\u0131 iddias\u0131ndan hareket eder. Teist yorum: Evren ya\u015fama izin verecek \u015fekilde takdir edilmi\u015ftir.",B.b_8,"orta-y\xfcksek",B.Ag,B.awZ)
