B.akT=new A.b("DELIL-0074","F\u0131trat, Ahlak ve \u0130nsan Delilleri","\u0130\xe7 d\xfcnya ve toplum","Din\xee Tecr\xfcbe Delili","Milyonlarca insan dua, ibadet ve tevbe i\xe7inde Allah\u2019a yak\u0131nl\u0131k ya\u015far.","Ki\u015fisel tecr\xfcbe herkes i\xe7in zorlay\u0131c\u0131 kan\u0131t olmayabilir; ama ya\u015fayan ki\u015fi i\xe7in g\xfc\xe7l\xfc delildir. Birikimli olarak da insanl\u0131k tarihinde ihmal edilemeyecek bir veri alan\u0131d\u0131r.",B.b46,"orta",B.bo,B.atq)
