B.aj9=new A.b("DELIL-0088","\u0130tirazlar ve Cevap Kartlar\u0131","Ateizm, \u015f\xfcphe ve kar\u015f\u0131 arg\xfcmanlar","G\xf6rm\xfcyorum, O Halde Yok mu?","G\xf6r\xfcnmezlik yoklukla ayn\u0131 de\u011fildir.","Ak\u0131l, bilin\xe7, yasa, matematiksel yap\u0131 ve anlam da g\xf6zle do\u011frudan g\xf6r\xfclmez; etkileriyle bilinir. Allah inanc\u0131 da do\u011frudan duyusal nesne de\u011fil, varl\u0131\u011f\u0131n nihai a\xe7\u0131klamas\u0131d\u0131r.",B.aKf,"orta",B.bo,B.arV)
