B.afZ=new A.b("DELIL-0090","\u0130tirazlar ve Cevap Kartlar\u0131","Ateizm, \u015f\xfcphe ve kar\u015f\u0131 arg\xfcmanlar","K\xf6t\xfc Dindarlar \u0130tiraz\u0131","\u0130nananlar\u0131n hatas\u0131, inanc\u0131n hakikatini otomatik \xe7\xfcr\xfctmez.","Matematik bilen birinin yanl\u0131\u015f hesap yapmas\u0131 matemati\u011fi \xe7\xfcr\xfctmez. Din de mensuplar\u0131n\u0131n k\xf6t\xfc temsilinden ba\u011f\u0131ms\u0131z olarak hakikat iddias\u0131na g\xf6re de\u011ferlendirilmelidir.",B.aYa,"orta",B.bo,B.amv)
