B.anK=new A.e(u._,u.S,"Bu kart, fiziksel evrenin yaln\u0131zca var olmas\u0131n\u0131 de\u011fil, \xf6l\xe7\xfclebilir ve ya\u015fam\u0131 m\xfcmk\xfcn k\u0131lan bir d\xfczen i\xe7inde var olmas\u0131n\u0131 merkeze al\u0131r. Sabitler, kuvvetler, ba\u015flang\u0131\xe7 ko\u015fullar\u0131 ve enerji dengeleri k\xfc\xe7\xfck de\u011fi\u015fimlere duyarl\u0131 oldu\u011funda, \u201cneden b\xf6yle?\u201d sorusu g\xfc\xe7lenir. Do\u011fal a\xe7\u0131klamalar bu mekanizmalar\u0131 tasvir edebilir; fakat d\xfczenin nihai zemini ayr\u0131 bir felsefi sorudur. Teist yorum, bu uygunlu\u011fu ilim, kudret ve hikmet sahibi bir yarat\u0131\u015f\u0131n izi olarak okur. Bu nedenle \u201cJ\xfcpiter Kalkan\u0131 Delili\u201d tek ba\u015f\u0131na kapal\u0131 bir slogan de\u011fil, bir a\xe7\u0131klama aray\u0131\u015f\u0131d\u0131r. Kart\u0131n k\u0131sa iddias\u0131 \u015fudur: B\xfcy\xfck gezegenler k\xfc\xe7\xfck cisimlerin y\xf6r\xfcngelerini etkileyerek sistemi \u015fekillendirir. Bu iddia do\u011frudan g\xf6zlenen olgu ile nihai metafizik a\xe7\u0131klama aras\u0131ndaki ba\u011f\u0131 kurar. Allah\u2019\u0131n varl\u0131\u011f\u0131 lehine de\u011feri, bu olgunun tesad\xfcf, k\xf6r zorunluluk veya a\xe7\u0131klamas\u0131z kabul ile b\u0131rak\u0131ld\u0131\u011f\u0131nda eksik kalmas\u0131d\u0131r.")
B.ajB=new A.b("DELIL-0152","Fizik ve Kozmoloji Delilleri","Evrenin fiziksel yap\u0131s\u0131","J\xfcpiter Kalkan\u0131 Delili","B\xfcy\xfck gezegenler k\xfc\xe7\xfck cisimlerin y\xf6r\xfcngelerini etkileyerek sistemi \u015fekillendirir.","J\xfcpiter\u2019in G\xfcne\u015f Sistemi dinami\u011findeki rol\xfc, ya\u015fanabilir gezegen tart\u0131\u015fmalar\u0131nda an\u0131l\u0131r. Uygulamada kesin \u2018tam korur\u2019 dili yerine \u2018sistem dinami\u011finde \xf6nemli rol oynar\u2019 denmelidir.",B.aOt,"d\xfc\u015f\xfck-orta",B.e,B.anK)
