B.akl=new A.b("DELIL-0332","Biyolojik Deliller","Kullan\u0131c\u0131 ek listesi","Ribozom: Protein Fabrikas\u0131","H\xfccredeki devasa \xfcretim tesisi.","Ribozom, genetik bilgiyi okuyup saniyeler i\xe7inde hatas\u0131z proteinlere d\xf6n\xfc\u015ft\xfcr\xfcr. Bu h\u0131z ve hassasiyet, tesad\xfcf kavram\u0131yla a\xe7\u0131klanamaz.",B.e,"orta",B.t,B.at7)
