B.afu=new A.b("DELIL-0341","Biyolojik Deliller","Kullan\u0131c\u0131 ek listesi","B\xf6breklerdeki Nefron S\xfczge\xe7leri","Dakikada litlerce kan\u0131 s\xfczen mikro-laboratuvar.","Nefronlar, faydal\u0131 maddeleri tutup zararl\u0131lar\u0131 atar. Bu se\xe7ici ge\xe7irgenlik, ya\u015fam\u0131n devam\u0131 i\xe7in olmazsa olmazd\u0131r.",B.e,"orta",B.t,B.anf)
