B.acK=new A.b("DELIL-0357","Fizik ve Kozmoloji Delilleri","Kullan\u0131c\u0131 ek listesi","Zay\u0131f N\xfckleer Kuvvet ve S\xfcpernovalar","Y\u0131ld\u0131zlar\u0131n patlamas\u0131yla yay\u0131lan ya\u015fam malzemeleri.","Zay\u0131f kuvvet, y\u0131ld\u0131zlar\u0131n a\u011f\u0131r elementleri evrene sa\xe7mas\u0131n\u0131 sa\u011flar. Bu kuvvet olmasayd\u0131 ya\u015fam i\xe7in gerekli demir ve karbon asla bize ula\u015famazd\u0131.",B.e,"orta",B.t,B.aoq)
