B.akc=new A.b("DELIL-0364","Fizik ve Kozmoloji Delilleri","Kullan\u0131c\u0131 ek listesi","Pauli D\u0131\u015flama \u0130lkesi","Maddenin neden birbirinin i\xe7inden ge\xe7medi\u011fi.","Bu ilke olmasayd\u0131 t\xfcm elektronlar ayn\u0131 yere \xe7\xf6ker ve kat\u0131 madde olu\u015famazd\u0131. D\xfcnyan\u0131n \xfczerinde y\xfcr\xfcyebilmemiz bu fizik kural\u0131na ba\u011fl\u0131d\u0131r.",B.e,"orta",B.t,B.aAg)
